import asyncioimport base64import hashlibimport hmacimport jsonimport loggingimport osimport timefrom datetime import datetime, timezonefrom typing import Optionalimport requestsimport websocketsfrom market_data import (    MarketDataStore,    OrderBookStore,    PositionUpdateStore,    SymbolRanker,    TradeStore,    Signal,)from strategy import StrategyContext, StrategyEngine, load_strategyfrom okx_futures_client import OKXFuturesClientfrom execution_engine import DemoFuturesExecutionEngine, ExecutionConfigfrom position_store import PositionHistoryStorefrom movement_tracker import MovementTracker, TradeSnapshotStore, MovementTrackerConfigfrom tp_tracker import TPTracker, TPTrackerConfiglogging.basicConfig(    level=logging.INFO,    format="%(message)s",    handlers=[logging.FileHandler("okx_futures.log"), logging.StreamHandler()],)log = logging.getLogger()logging.getLogger("httpx").setLevel(logging.WARNING)logging.getLogger("httpcore").setLevel(logging.WARNING)STRATEGY_NAME = "vwap_3stage_engine"STRATEGY_TICK_INTERVAL_SEC = 2.0STRATEGY_SNAPSHOT_LOG_INTERVAL_SEC = 120.0STRATEGY_OVERRIDES = {    "observation_engine": dict(        max_observation_minutes=6.0,        trend_candle_bar="1m",        bucket_count=5,        window_ms=240_000,        min_trend_strength_pct=65.0,        min_net_move_pct=0.0015,        min_buy_pressure_strength_pct=65.0,        min_volume_expansion_strength_pct=55.0,        volume_expansion_multiplier=1.4,    ),    "vwap_stg": {},    "vwap_3stage_engine": {},    "ema_stg": {},}STRATEGY_TRADE_WINDOW_MS = {    "observation_engine": STRATEGY_OVERRIDES["observation_engine"]["window_ms"],    "vwap_3stage_engine": STRATEGY_OVERRIDES["vwap_3stage_engine"].get("window_ms", 240_000),    "vwap_stg": STRATEGY_OVERRIDES["vwap_stg"].get("window_ms", 600_000),}_active_strategy_window_ms = STRATEGY_TRADE_WINDOW_MS.get(STRATEGY_NAME)TRADE_WINDOWS_MS = (500, 1000, 2000, 5000) + (    (_active_strategy_window_ms,) if _active_strategy_window_ms else ())DEMO_TRADING = TruePROD_PUBLIC_WS = "wss://ws.okx.com:8443/ws/v5/public"PROD_PRIVATE_WS = "wss://ws.okx.com:8443/ws/v5/private"DEMO_PUBLIC_WS = "wss://wspap.okx.com:8443/ws/v5/public"DEMO_PRIVATE_WS = "wss://wspap.okx.com:8443/ws/v5/private"PUBLIC_WS_URL = DEMO_PUBLIC_WS if DEMO_TRADING else PROD_PUBLIC_WSPRIVATE_WS_URL = DEMO_PRIVATE_WS if DEMO_TRADING else PROD_PRIVATE_WSPING_INTERVAL_SEC = 15RECONNECT_BASE_DELAY_SEC = 3RECONNECT_MAX_DELAY_SEC = 60HEARTBEAT_INTERVAL_SEC = 30TICKER_CHANNEL = "tickers"DEPTH_CHANNEL = "books5"DEPTH_LEVELS = 5TRADE_CHANNEL = "trades"POSITIONS_CHANNEL = "positions"SUBSCRIBE_BATCH_SIZE = 50WATCHLIST_TOP_N = 15WATCHLIST_WARMUP_SEC = 10WATCHLIST_INTERVAL_SEC = 30SYMBOL_STALE_AFTER_SEC = 30POSITION_MONITOR_INTERVAL_SEC = 5.0MARGIN_PER_TRADE_USDT = 5.0REQUESTED_LEVERAGE = 50MIN_LEVERAGE_REQUIRED = 10MAX_OPEN_POSITIONS = 5MAX_TOTAL_TRADES = 100TARGET_NET_PROFIT_USDT = 0.5TARGET_STOP_LOSS_USDT = 0.9SL_LIMIT_SLIPPAGE_PCT = 0.0025TP_TRACKER_ENABLED = FalseTRAILING_TP_ACTIVATION_USDT = 0.20TRAILING_TP_LAG_USDT = 0.10OPEN_TYPE = "isolated"BLACKLISTED_SYMBOLS = {"BTC-USDT-SWAP"}STATUS_LOG_INTERVAL_SEC = 30.0class WatchlistState:    def __init__(self) -> None:        self.symbols = set()        self.paused = Falsedef _load_db_config() -> dict:    here = os.path.dirname(os.path.abspath(__file__))    candidates = [        os.path.join(here, "db.txt"),        os.path.join(os.path.dirname(here), "db.txt"),    ]    for path in candidates:        if os.path.exists(path):            config = {}            with open(path, "r") as f:                for line in f:                    line = line.strip()                    if not line or line.startswith("#"):                        continue                    if "=" in line:                        k, _, v = line.partition("=")                        config[k.strip()] = v.strip().strip('"')            return config    raise FileNotFoundError(f"db.txt not found in any of: {candidates}")def _clean_secret(value):    if value is None:        return None    if isinstance(value, str):        value = value.strip()        if value.upper() in ("", "NULL"):            return None    return valuedef load_okx_credentials() -> dict:    """Looks for the 'okx' row in the api_keys Supabase table. OKX needs a    passphrase in addition to key/secret (set by you when the key was    created on OKX), so that column has to be populated for this to work.    Mirrors test_ws.py's load_okx_credentials()."""    from supabase import create_client    config = _load_db_config()    sb = create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])    rows = sb.table("api_keys").select("*").execute()    match = next(        (r for r in rows.data or [] if (r.get("exchange_name") or "").strip().lower() == "okx"),        None,    )    if not match:        raise RuntimeError("No 'okx' row found in the api_keys Supabase table")    api_key = _clean_secret(match.get("api_key_demo"))    api_secret = _clean_secret(match.get("api_secret_demo"))    passphrase = _clean_secret(match.get("passphrase"))    missing = [n for n, v in (("api_key", api_key), ("api_secret", api_secret), ("passphrase", passphrase)) if not v]    if missing:        raise RuntimeError(f"OKX credentials incomplete in Supabase — missing: {', '.join(missing)}")    return {"api_key": api_key, "api_secret": api_secret, "passphrase": passphrase}def build_supabase_client():    """Separate client for position_history reads/writes — reuses the same    db.txt config as load_okx_credentials() but keeps that function's    signature (and its callers) unchanged."""    from supabase import create_client    config = _load_db_config()    return create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])def get_outbound_ip():    try:        resp = requests.get("https://api.ipify.org?format=json", timeout=5)        return resp.json().get("ip")    except Exception:        return Nonedef build_login_args(api_key: str, api_secret: str, passphrase: str) -> dict:    timestamp = str(int(time.time()))    message = f"{timestamp}GET/users/self/verify"    sign = base64.b64encode(        hmac.new(api_secret.encode(), message.encode(), hashlib.sha256).digest()    ).decode()    return {"apiKey": api_key, "passphrase": passphrase, "timestamp": timestamp, "sign": sign}async def _keepalive(ws):    while True:        await asyncio.sleep(PING_INTERVAL_SEC)        try:            await ws.send("ping")        except Exception:            returndef _depth_trade_args(symbols) -> list:    args = []    for s in symbols:        args.append({"channel": DEPTH_CHANNEL, "instId": s})        args.append({"channel": TRADE_CHANNEL, "instId": s})    return argsasync def _send_in_batches(ws, op: str, args: list) -> None:    for i in range(0, len(args), SUBSCRIBE_BATCH_SIZE):        batch = args[i : i + SUBSCRIBE_BATCH_SIZE]        await ws.send(json.dumps({"op": op, "args": batch}))async def _watchlist_loop(ws, ranker: SymbolRanker, order_book: OrderBookStore, trade_store: TradeStore, watchlist_state: WatchlistState):    current = set()    await asyncio.sleep(WATCHLIST_WARMUP_SEC)    while True:        if watchlist_state.paused:            await asyncio.sleep(WATCHLIST_INTERVAL_SEC)            continue        top = set(await ranker.top_symbols()) - BLACKLISTED_SYMBOLS        added = top - current        removed = current - top        if removed:            await _send_in_batches(ws, "unsubscribe", _depth_trade_args(removed))            for symbol in removed:                await order_book.remove(symbol)                await trade_store.remove(symbol)        if added:            await _send_in_batches(ws, "subscribe", _depth_trade_args(added))        if added or removed:            current = top            watchlist_state.symbols = set(current)            log.info(f"[watchlist] now tracking {sorted(current)}")        await asyncio.sleep(WATCHLIST_INTERVAL_SEC)def _translate_ticker(row: dict) -> dict:    """OKX 'tickers' channel -> the ticker shape MarketDataStore/SymbolRanker    expect. OKX has no mark-price field on this channel, so mark_price is    approximated with last_price here — fine for signal generation (which    doesn't read mark_price), but monitor_positions() uses the *real*    mark price from get_position() for anything that matters financially."""    pct_change = None    try:        last = float(row.get("last"))        open24h = float(row.get("open24h"))        if open24h:            pct_change = (last - open24h) / open24h    except (TypeError, ValueError):        pass    return {        "symbol": row.get("instId"),        "last_price": row.get("last"),        "mark_price": row.get("last"),        "bid_price": row.get("bidPx"),        "ask_price": row.get("askPx"),        "bid_vol": row.get("bidSz"),        "ask_vol": row.get("askSz"),        "volume_24": row.get("vol24h"),        "range": pct_change if pct_change is not None else 0.0,    }async def _apply_book_snapshot(order_book: OrderBookStore, row: dict) -> None:    """OKX 'books5' pushes a full top-5 snapshot every update (no deltas to    merge), so each side is just replaced wholesale via the existing    apply_depth_update(), same as it already does per-side."""    inst_id = row.get("instId")    if not inst_id:        return    bids = [{"price": lvl[0], "vol": lvl[1]} for lvl in (row.get("bids") or []) if len(lvl) >= 2]    asks = [{"price": lvl[0], "vol": lvl[1]} for lvl in (row.get("asks") or []) if len(lvl) >= 2]    await order_book.apply_depth_update({"symbol": inst_id, "way": 1, "depths": bids})    await order_book.apply_depth_update({"symbol": inst_id, "way": 2, "depths": asks})def _translate_trade(row: dict) -> dict:    return {        "symbol": row.get("instId"),        "price": row.get("px"),        "vol": row.get("sz"),        "side": row.get("side"),        "created_at": row.get("ts"),    }def _translate_position(row: dict) -> dict:    """OKX 'positions' channel push -> the same shape    OKXFuturesClient.get_position() already produces per-row, so any    consumer of that REST shape can consume this push identically.    `instId` isn't part of that REST shape (the REST call is already    scoped to one symbol) but IS needed here since a single push can    cover multiple symbols at once -- included as "symbol" for the    caller to key on."""    try:        current_amount = abs(float(row.get("pos", 0)))    except (TypeError, ValueError):        current_amount = 0.0    return {        "symbol": row.get("instId"),        "current_amount": current_amount,        "mark_price": row.get("markPx"),        "unrealized_pnl": row.get("upl"),        "liquidation_price": row.get("liqPx"),        "avg_price": row.get("avgPx"),        "raw": row,    }async def run_public(    market_data: MarketDataStore,    order_book: OrderBookStore,    ranker: SymbolRanker,    trade_store: TradeStore,    watchlist_state: WatchlistState,    all_symbols: list,):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[public] connecting to {PUBLIC_WS_URL}")            async with websockets.connect(PUBLIC_WS_URL, ping_interval=None) as ws:                log.info("[public] connected")                delay = RECONNECT_BASE_DELAY_SEC                ticker_args = [{"channel": TICKER_CHANNEL, "instId": s} for s in all_symbols]                await _send_in_batches(ws, "subscribe", ticker_args)                keepalive_task = asyncio.create_task(_keepalive(ws))                watchlist_task = asyncio.create_task(_watchlist_loop(ws, ranker, order_book, trade_store, watchlist_state))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[public] non-JSON message: {raw[:200]}")                            continue                        event = msg.get("event")                        arg = msg.get("arg") or {}                        channel = arg.get("channel")                        if event == "subscribe":                            continue                        elif event == "unsubscribe":                            continue                        elif event == "error":                            log.error(f"[public] \u274c error: {msg}")                        elif channel == TICKER_CHANNEL:                            for row in msg.get("data") or []:                                ticker = _translate_ticker(row)                                await market_data.update_from_ticker(ticker)                                await ranker.update_from_ticker(ticker)                        elif channel == DEPTH_CHANNEL:                            for row in msg.get("data") or []:                                await _apply_book_snapshot(order_book, row)                        elif channel == TRADE_CHANNEL:                            for row in msg.get("data") or []:                                await trade_store.apply_trade(_translate_trade(row))                finally:                    keepalive_task.cancel()                    watchlist_task.cancel()        except Exception as e:            log.error(f"[public] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def run_heartbeat(market_data: MarketDataStore, order_book: OrderBookStore):    while True:        await asyncio.sleep(HEARTBEAT_INTERVAL_SEC)        symbol_count = await market_data.symbol_count()        book_count = len(await order_book.symbols())        log.info(f"[heartbeat] tracking {symbol_count} tickers, {book_count} order books")THIN_SEPARATOR = "-" * 40def _log_signal(signal: Signal) -> None:    log.info(THIN_SEPARATOR)    log.info(f"[strategy] ACCEPTED {signal.symbol} {signal.direction.upper()} — {'; '.join(signal.reasons)}")    log.info(THIN_SEPARATOR)async def run_trading_loop(    market_data: MarketDataStore,    strategy_engine: StrategyEngine,    execution_engine: DemoFuturesExecutionEngine,    watchlist_state: WatchlistState,):    """Watchlist -> StrategyEngine -> ExecutionEngine.    This is the entire trade-decision path, and it's strategy-agnostic —    `strategy_engine` is whichever module STRATEGY_NAME picked in main()    (observation_engine.py by default; see strategy/base.py's module    docstring for the interface every strategy implements and    strategy/ for the full list). A symbol becomes a candidate the    moment it enters the watchlist (sync_watchlist) and is re-checked    every tick via evaluate(), which returns a ready-to-open    market_data.Signal the instant that strategy's own entry conditions    are met, or None otherwise — this loop doesn't know or care what    those conditions actually are.    """    was_blocked = False    last_status_log = 0.0    last_observation_log = 0.0    while True:        await asyncio.sleep(STRATEGY_TICK_INTERVAL_SEC)        open_count = await execution_engine.open_count()        total_opened = await execution_engine.total_opened()        max_positions = execution_engine.config.max_open_positions        max_total = execution_engine.config.max_total_trades        capacity_block = open_count >= max_positions        total_block = max_total is not None and total_opened >= max_total        blocked = capacity_block or total_block        if blocked and not was_blocked:            reason = (                f"lifetime trade limit reached ({total_opened}/{max_total})"                if total_block                else f"{open_count}/{max_positions} positions open"            )            log.info(                f"[execution] {reason} — pausing signal scans and watchlist subscriptions, "                f"monitoring existing trades only"            )            last_status_log = time.time()        elif was_blocked and not blocked:            log.info(f"[execution] slot freed ({open_count}/{max_positions} open) — resuming signal scans")        was_blocked = blocked        watchlist_state.paused = blocked        if blocked:            now = time.time()            if now - last_status_log >= STATUS_LOG_INTERVAL_SEC:                log.info(                    f"[status] {open_count}/{max_positions} open positions, "                    f"{total_opened}/{max_total} lifetime trades — monitoring only"                )                last_status_log = now            continue        await strategy_engine.sync_watchlist(watchlist_state.symbols)        for symbol in list(watchlist_state.symbols):            if symbol in BLACKLISTED_SYMBOLS:                continue            if await execution_engine.is_blacklisted(symbol):                continue            if await execution_engine.open_count() >= execution_engine.config.max_open_positions:                break            if await execution_engine.has_open_position(symbol):                continue            market = await market_data.get(symbol)            if not market:                continue            signal = await strategy_engine.evaluate(symbol)            if signal is None:                continue            _log_signal(signal)            await execution_engine.try_open_trade(signal)        now = time.time()        if now - last_observation_log >= STRATEGY_SNAPSHOT_LOG_INTERVAL_SEC:            candidates = await strategy_engine.snapshot()            if candidates:                parts = [c.status_line() for c in sorted(candidates, key=lambda c: c.symbol)]                log.info(f"[{strategy_engine.name}] watching {len(candidates)}: {'; '.join(parts)}")            else:                log.info(f"[{strategy_engine.name}] no candidates currently being observed")            last_observation_log = nowasync def run_position_monitor(execution_engine: DemoFuturesExecutionEngine):    while True:        await asyncio.sleep(POSITION_MONITOR_INTERVAL_SEC)        try:            await execution_engine.monitor_positions()        except Exception:            log.exception("[monitor] error while monitoring open positions")async def run_shutdown_watcher(execution_engine: DemoFuturesExecutionEngine, shutdown_event: asyncio.Event):    """Once the lifetime trade cap has been reached and every trade opened    under it has closed, signal main() to stop the bot so the run can be    reviewed from position_history rather than trading indefinitely."""    while True:        await asyncio.sleep(POSITION_MONITOR_INTERVAL_SEC)        if await execution_engine.trades_exhausted():            total = await execution_engine.total_opened()            log.info(                f"[shutdown] lifetime trade limit reached ({total}/{execution_engine.config.max_total_trades}) "                f"and all positions are closed — stopping the bot for manual review of position_history"            )            shutdown_event.set()            returnasync def run_private(    creds: dict,    tp_tracker=None,    position_updates: Optional[PositionUpdateStore] = None,    execution_engine=None,    ready_event: Optional[asyncio.Event] = None,):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[private] connecting to {PRIVATE_WS_URL}")            async with websockets.connect(PRIVATE_WS_URL, ping_interval=None) as ws:                log.info("[private] connected \u2014 logging in")                delay = RECONNECT_BASE_DELAY_SEC                login_args = build_login_args(creds["api_key"], creds["api_secret"], creds["passphrase"])                await ws.send(json.dumps({"op": "login", "args": [login_args]}))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[private] non-JSON message: {raw[:200]}")                            continue                        event = msg.get("event")                        arg = msg.get("arg") or {}                        channel = arg.get("channel")                        if event == "login":                            if msg.get("code") == "0":                                log.info("[private] \u2705 login successful")                                await ws.send(json.dumps({                                    "op": "subscribe",                                    "args": [{"channel": POSITIONS_CHANNEL, "instType": "SWAP"}],                                }))                                if ready_event is not None:                                    ready_event.set()                            else:                                log.error(f"[private] \u274c login failed: {msg}")                                log.error("[private] if this key requires IP whitelisting, confirm this machine's outbound IP is whitelisted on OKX")                                await asyncio.sleep(RECONNECT_MAX_DELAY_SEC)                        elif event == "subscribe":                            continue                        elif event == "error":                            log.error(f"[private] \u274c error: {msg}")                        elif event == "channel-conn-count":                            continue                        elif channel == POSITIONS_CHANNEL:                            for row in msg.get("data") or []:                                position = _translate_position(row)                                symbol = position["symbol"]                                if not symbol:                                    continue                                if position_updates is not None:                                    await position_updates.apply_update(position)                                if tp_tracker is not None and position["current_amount"] > 0:                                    try:                                        pnl = float(position["unrealized_pnl"])                                    except (TypeError, ValueError):                                        pnl = None                                    if pnl is not None:                                        await tp_tracker.observe(symbol, pnl)                                        if execution_engine is not None:                                            await execution_engine.maybe_ratchet_stop_loss_for(symbol)                        else:                            log.info(f"[private] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[private] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def main():    creds = load_okx_credentials()    outbound_ip = get_outbound_ip()    log.info(f"Outbound IP for this machine: {outbound_ip or 'could not determine'}")    log.info(f"Starting OKX Futures bot (demo_trading={DEMO_TRADING})")    okx_client = OKXFuturesClient(        api_key=creds["api_key"],        api_secret=creds["api_secret"],        passphrase=creds["passphrase"],        demo_trading=DEMO_TRADING,    )    instruments = await okx_client.list_swap_instruments()    all_symbols = [i["instId"] for i in instruments if i.get("instId")]    log.info(f"[startup] discovered {len(all_symbols)} live USDT-margined swap instruments")    market_data = MarketDataStore()    order_book = OrderBookStore(depth_levels=DEPTH_LEVELS)    ranker = SymbolRanker(top_n=WATCHLIST_TOP_N, stale_after_sec=SYMBOL_STALE_AFTER_SEC)    trade_store = TradeStore(windows_ms=TRADE_WINDOWS_MS)    trade_store.on_unmapped_way = lambda way, payload: log.warning(f"[trade] unmapped way={way!r} — trade skipped: {payload}")    position_updates = PositionUpdateStore()    position_store = None    try:        position_store = PositionHistoryStore(build_supabase_client())    except Exception:        log.exception("[position-store] could not initialize — continuing without trade persistence")    tp_tracker = TPTracker(        TPTrackerConfig(            activation_profit_usdt=TRAILING_TP_ACTIVATION_USDT,            trail_lag_usdt=TRAILING_TP_LAG_USDT,            final_take_profit_usdt=TARGET_NET_PROFIT_USDT,        )    )    movement_tracker = None    try:        movement_tracker = MovementTracker(            market_data, TradeSnapshotStore(build_supabase_client()), MovementTrackerConfig()        )    except Exception:        log.exception("[movement-tracker] could not initialize — continuing without trade movement tracking")    strategy_engine = load_strategy(        STRATEGY_NAME,        StrategyContext(            market_data=market_data,            trade_store=trade_store,            candle_fetcher=okx_client.get_candles,            okx_client=okx_client,            config_overrides=STRATEGY_OVERRIDES.get(STRATEGY_NAME, {}),        ),    )    log.info(f"[strategy] using '{strategy_engine.name}' (strategy/{STRATEGY_NAME}.py)")    execution_engine = DemoFuturesExecutionEngine(        okx_client,        ExecutionConfig(            margin_per_trade_usdt=MARGIN_PER_TRADE_USDT,            requested_leverage=REQUESTED_LEVERAGE,            min_leverage_required=MIN_LEVERAGE_REQUIRED,            max_open_positions=MAX_OPEN_POSITIONS,            max_total_trades=MAX_TOTAL_TRADES,            target_net_profit_usdt=TARGET_NET_PROFIT_USDT,            target_stop_loss_usdt=TARGET_STOP_LOSS_USDT,            sl_limit_slippage_pct=SL_LIMIT_SLIPPAGE_PCT,            enable_trailing_tp=TP_TRACKER_ENABLED,            trailing_tp_activation_usdt=TRAILING_TP_ACTIVATION_USDT,            trailing_tp_lag_usdt=TRAILING_TP_LAG_USDT,            open_type=OPEN_TYPE,        ),        position_store=position_store,        movement_tracker=movement_tracker,        tp_tracker=tp_tracker,    )    log.info(f"[tp-tracker] trailing profit floor {'enabled' if TP_TRACKER_ENABLED else 'disabled'}")    watchlist_state = WatchlistState()    shutdown_event = asyncio.Event()    private_ready_event = asyncio.Event()    tasks = [        asyncio.create_task(run_public(market_data, order_book, ranker, trade_store, watchlist_state, all_symbols)),        asyncio.create_task(run_private(            creds,            tp_tracker=tp_tracker,            position_updates=position_updates,            execution_engine=execution_engine,            ready_event=private_ready_event,        )),    ]    await private_ready_event.wait()    if position_store is not None:        await execution_engine.reconcile_from_store(position_store)    tasks.extend([        asyncio.create_task(run_heartbeat(market_data, order_book)),        asyncio.create_task(run_trading_loop(market_data, strategy_engine, execution_engine, watchlist_state)),        asyncio.create_task(run_position_monitor(execution_engine)),        asyncio.create_task(run_shutdown_watcher(execution_engine, shutdown_event)),    ])    if movement_tracker is not None:        tasks.append(asyncio.create_task(movement_tracker.run_forever()))    await shutdown_event.wait()    for task in tasks:        task.cancel()    await asyncio.gather(*tasks, return_exceptions=True)    log.info("[shutdown] all background tasks stopped — exiting")if __name__ == "__main__":    try:        asyncio.run(main())    except KeyboardInterrupt:        log.info("okx_futures.py stopped.")